import mpi4py.MPI as MPI
import math
import sys

def read_data(filename):
    data = []
    with open(filename, 'r') as f:
        for line in f:
            line = line.strip()
            if line:
                row = list(map(int, line.split()))
                data.append(row)
    return data

def main():
    comm = MPI.COMM_WORLD
    rank = comm.Get_rank()
    size = comm.Get_size()

    start_time = MPI.Wtime()

    try:
        data = read_data(f"data_{rank}.txt")
    except FileNotFoundError:
        if rank == 0:
            print("Error: Input files not found")
        comm.Abort()
        return

    b = data[0]
    n = len(b)

    if rank == 0:
        c = [0] * n
    else:
        stp = n // size + (1 if (n % size > rank) else 0)
        c = [0] * stp

    ia = data[1]
    ja = data[2]
    an = data[3]

    stp = n // size + (1 if (n % size > rank) else 0)

    for i in range(stp):
        strt = ia[i] - ia[0]
        lstr = ia[i + 1] - ia[i]
        for j in range(lstr):
            c[i] += an[strt + j] * b[ja[strt + j]]

    if rank == 0:
        for i in range(1, size):
            recv_stp = n // size + (1 if (n % size > i) else 0)
            recv_buf = comm.recv(source=i, tag=0)

            offset = 0
            for k in range(i):
                offset += n // size + (1 if (n % size > k) else 0)

            for j in range(recv_stp):
                c[offset + j] = recv_buf[j]
    else:
        comm.send(c, dest=0, tag=0)

    if rank == 0:
        end_time = MPI.Wtime()
        for val in c:
            print(val)
        print(f"Success! Time = {end_time - start_time}")

if __name__ == "__main__":
    main()
